FILTER_PAGES = {
    "wave": ("Wave Flow", "warps regions into flowing directional bands"),
    "voronoi": ("Voronoi", "divides regions into cell-like geometric territories"),
    "shear": ("Shear", "offsets geometry into a slanted directional treatment"),
    "spiral": ("Spiral Vortex", "rotates geometry around a vortex-like field"),
    "mosaic": ("Staggered Mosaic", "rebuilds regions as offset tile-like blocks"),
    "crystal": ("Crystal Tessellation", "divides color regions into crystalline polygonal structures"),
    "ripple": ("Topographic Ripple", "introduces repeated contour-like displacement"),
    "glitch": ("Digital Glitch", "divides the geometry matching each Rasterizer swatch into horizontal bands and rectangular fragments, then selectively offsets and repeats those fragments to create a controlled digital-signal distortion"),
    "deep-fryer": ("Deep Fryer", "divides the geometry matching each Rasterizer swatch into compression-like blocks and horizontal bands, removes some fragments, and shifts or repeats others to imitate heavily compressed, repeatedly copied digital artwork"),
    "shattered": ("Shattered", "divides the geometry matching each Rasterizer swatch into irregular shards, opens cracks between them, and moves and rotates the pieces relative to a selected break origin so the artwork appears to spread and fall apart"),
    "structure-tensor-flow": ("Structure Tensor Flow", "calculates a directional field from source-image edges and rebuilds every color region as curved ribbons following that local contour flow"),
    "optical-color-mix": ("Optical Color Mix", "samples the original image colors and approximates colors unavailable as direct swatches with deterministic two-swatch dot mixtures"),
}
CONTROL_GUIDES = {
    "min_island_area": ("Minimum island area", "Removes isolated color regions smaller than the selected raster-area threshold. Each footprint transfers to the touching swatch that shares the most pixel sides; Black is used only when no swatch touches it.", "Like removing a tiny mosaic tile and giving its space to the neighboring color wrapped around most of its edges."),
    "simplification_factor": ("Simplification", "Reduces small boundary bends and vector points while retaining the larger silhouette.", "Like tracing a coastline with a broader pencil that skips the smallest coves."),
    "smoothing_radius": ("Smoothing radius", "Rounds small corners and calms jagged region boundaries.", "Like sanding a cut edge with progressively more rounding pressure."),
    "transparent": ("Transparent light areas", "Leaves the light half of the black-and-white result unengraved instead of exporting light geometry.", "Like printing black ink on clear film and treating the unprinted film as empty space."),
    "amplitude_x": ("Horizontal amplitude", "Controls the maximum side-to-side displacement applied by the wave transformation.", "Like changing how far a flag can swing from side to side in the wind."),
    "amplitude_y": ("Vertical amplitude", "Controls the maximum up-and-down displacement applied by the wave transformation.", "Like changing the height of waves moving across the surface of water."),
    "frequency_x": ("Horizontal frequency", "Controls how rapidly the up-and-down displacement repeats across the artwork's width, with higher values fitting more wave cycles into the same distance.", "Like fitting more wave crests along a rope without changing the rope's length."),
    "frequency_y": ("Vertical frequency", "Controls how rapidly the side-to-side displacement repeats down the artwork's height, with higher values fitting more wave cycles into the same distance.", "Like moving repeated contour lines closer together so more of them fit within the same height."),
    "phase": ("Phase", "Shifts the starting position of the wave cycle without changing its amplitude or frequency.", "Like sliding a sheet of striped wallpaper sideways without changing the width or spacing of its stripes."),
    "cell_size": ("Cell size", "Controls the approximate scale of generated cells or facets, with larger values generally producing larger and fewer subdivisions.", "Like choosing large paving stones instead of many small mosaic pieces to cover the same area."),
    "jitter": ("Jitter", "Randomly offsets the regularly spaced cell seed points, with higher values producing a less uniform and more irregular cell pattern.", "Like nudging trees away from exact positions on a planting grid to make the arrangement look less regular."),
    "gap": ("Gap", "Controls the empty spacing between cells, tiles, or facets, with larger values widening the seams and reducing the filled area.", "Like widening the grout lines between floor tiles while leaving the tiles in place."),
    "seed": ("Seed", "Selects the random arrangement used by the preset; the same seed reproduces the same layout, while a different seed creates another variation.", "Like recording a shuffle number so the same deck order can be recreated later."),
    "shear_x": ("Horizontal shear", "Slants the geometry sideways by shifting horizontal position according to height; positive and negative values lean it in opposite directions.", "Like pushing the top of a stack of cards sideways while the bottom remains in place."),
    "shear_y": ("Vertical shear", "Slants the geometry vertically by shifting vertical position according to width; positive and negative values raise opposite sides.", "Like pushing one side of a flexible picture frame upward while the opposite side remains in place."),
    "scale_x": ("Horizontal scale", "Scales the geometry's width, with values below 1 compressing it and values above 1 stretching it horizontally.", "Like resizing a photograph horizontally while leaving its height unchanged."),
    "scale_y": ("Vertical scale", "Scales the geometry's height, with values below 1 compressing it and values above 1 stretching it vertically.", "Like resizing a photograph vertically while leaving its width unchanged."),
    "twist": ("Twist", "Controls the amount and direction of rotation around the selected center, with larger magnitudes producing a stronger twist and opposite signs reversing its direction.", "Like stirring paint clockwise or counterclockwise, with a larger motion creating a stronger swirl."),
    "falloff": ("Falloff", "Controls how quickly the twist increases with distance from the center, with higher values keeping the central area straighter and concentrating more rotation toward the outer areas.", "Like deciding whether a swirl spreads through most of a bowl or becomes strongest mainly near its outer edge."),
    "center_x": ("Center X", "Sets the horizontal position of the vortex center, where 0 is the left edge, 0.5 is the middle, and 1 is the right edge.", "Like moving the fixed point of a drawing compass from the left side of the page to the right."),
    "center_y": ("Center Y", "Sets the vertical position of the vortex center, where 0 is the top edge, 0.5 is the middle, and 1 is the bottom edge.", "Like moving the fixed point of a drawing compass from the top of the page to the bottom."),
    "tile_size": ("Tile size", "Controls the width and height of the mosaic blocks, with larger values producing larger and fewer tiles across the artwork.", "Like choosing between many small bathroom mosaic tiles and a smaller number of large floor tiles."),
    "stagger": ("Stagger", "Offsets every other tile row by a fraction of the tile width, where 0 keeps rows aligned and 0.5 creates a half-tile brick pattern.", "Like shifting every other row of graph-paper squares to create the repeating bond pattern of a brick wall."),
    "amplitude": ("Amplitude", "Controls the strength and direction of the radial ripple displacement, with larger magnitudes producing stronger distortion and opposite signs reversing the displacement pattern.", "Like changing how strongly a dropped stone pushes ripples across the surface of water."),
    "frequency": ("Frequency", "Controls how rapidly ripple cycles repeat with distance from the center, with higher values placing the concentric distortions closer together.", "Like reducing a topographic map's contour interval so more contour lines fit within the same distance."),
    "slice_height": ("Slice height", "Controls the height of the horizontal bands used to divide the artwork, with smaller values creating more bands and finer vertical segmentation.", "Like cutting a printed picture into thin or thick horizontal strips before sliding some of them out of alignment."),
    "fragment_width": ("Fragment width", "Controls the width of the rectangular pieces cut from each horizontal band, with smaller values dividing each band into more independently processed fragments.", "Like cutting each horizontal picture strip into short or long rectangular tiles that can be moved separately."),
    "shift_amount": ("Shift amount", "Sets the maximum horizontal displacement available to selected fragments, with larger values allowing the glitch pieces to move farther left or right from their original positions.", "Like sliding selected pieces of a cut-up picture sideways while the surrounding pieces remain in place."),
    "echo_count": ("Echo count", "Controls how many additional copies of each selected fragment are created beyond its first displaced copy, with 0 disabling the extra echoes.", "Adding repeats with an audio delay effect."),
    "echo_spacing": ("Echo spacing", "Controls the base horizontal distance between successive fragment echoes, with larger values spreading the repeated copies farther apart.", "Like changing the distance between repeated images in a photographic motion trail."),
    "density": ("Density", "Controls the proportion of fragments selected for displacement and echoes; fragments that are not selected remain in their original positions.", "Like choosing what percentage of tiles in a picture will be slid out of place while the rest remain untouched."),
    "fibonacci_stride": ("Fibonacci stride", "Controls how far the displacement pattern advances through its Fibonacci sequence between horizontal bands, changing how quickly the shift and echo spacing grow and shrink across the artwork.", "Like stepping through a repeating musical pattern one beat at a time or skipping ahead several beats whenever a new row begins."),
    "vertical_jitter": ("Vertical jitter", "Sets the total range of repeatable random vertical displacement applied to selected fragments; 0 keeps them aligned with their original bands, while larger values move them farther up or down.", "Like an old television picture whose horizontal bands wobble slightly upward and downward because the vertical alignment is unstable."),
    "block_size": ("Block size", "Controls the horizontal width of the compression-like rectangular fragments, with smaller values dividing each band into more independently processed blocks.", "Like cutting each horizontal strip of a picture into narrow or wide rectangular tiles that can be damaged separately."),
    "band_height": ("Band height", "Controls the vertical height of the horizontal rows used to divide the artwork, with smaller values creating more bands whose fragments can receive different damage patterns.", "Like slicing a printed picture into thin or thick horizontal strips before dragging each strip sideways by a different amount."),
    "compression_gap": ("Compression gap", "Shrinks each rectangular block before source geometry is collected from it, creating empty seams between neighboring fragments; larger values widen those seams.", "Like widening the missing mortar lines between damaged bricks so the individual blocks become more separated."),
    "smear_amount": ("Smear amount", "Controls the scale of horizontal displacement applied to each band and adds smaller fragment-level variations within it; larger values produce longer sideways smears.", "Wiping wet ink with a cloth."),
    "degradation": ("Degradation", "Increases the probability that fragments are removed and also increases the probability that the remaining fragments receive echoes, producing more missing and repeated geometry at higher values.", "Like repeatedly copying and resaving an image until some blocks disappear while others leave visible ghost copies."),
    "min_shard_size": ("Minimum shard size", "Sets the lower end of the approximate shard-size range used to build the fracture pattern; larger values generally produce larger and fewer shards, although individual irregular pieces can vary.", "Like choosing the smaller end of the piece-size range before breaking a sheet into an irregular mosaic."),
    "max_shard_size": ("Maximum shard size", "Sets the upper end of the approximate shard-size range used to build the fracture pattern; larger values allow the point spacing to grow and generally produce larger, less uniform pieces.", "Like choosing the larger end of the piece-size range before breaking a sheet into an irregular mosaic."),
    "minimum_gap": ("Minimum gap", "Sets the baseline amount by which every shard is contracted before it is moved, establishing the narrowest cracks in the fracture pattern; larger values create more separation.", "Choosing the thinnest grout line in a broken-tile mosaic."),
    "gap_variation": ("Gap variation", "Sets the maximum random amount added above Minimum Gap for individual shards; 0 keeps the contraction uniform, while larger values create more varied crack widths.", "Natural glass cracks opening by different amounts."),
    "horizontal_spread": ("Horizontal spread", "Controls the scale of sideways movement away from the Break Origin, with larger values allowing shards to travel farther left or right depending on which side of the origin they begin.", "Debris spreading outward after impact."),
    "fall_distance": ("Fall distance", "Controls the scale of downward movement applied to the shards, with larger values allowing pieces to drop farther by amounts that vary with their position and the generated fracture pattern.", "Broken pieces dropping under gravity."),
    "gravity_bias": ("Gravity bias", "Controls how strongly a shard's vertical position influences its overall movement; higher values keep upper and middle shards closer to their starting positions while concentrating stronger movement toward the bottom of the artwork.", "Like adjusting a gravity curve so upper pieces stay closer to the break while lower pieces pull away more strongly."),
    "rotation": ("Rotation", "Controls the scale of randomized clockwise and counterclockwise rotation applied to each shard, with larger values allowing the pieces to tumble more dramatically.", "Loose cards spinning as they fall."),
    "break_origin_x": ("Break origin X", "Sets the horizontal position of the fracture's reference point, where 0 is the left edge, 0.5 is the center, and 1 is the right edge; shards generally spread away from this position.", "Moving a hammer strike across glass."),
    "break_origin_y": ("Break origin Y", "Sets the vertical position of the fracture's reference point, where 0 is the top edge, 0.5 is the center, and 1 is the bottom edge; each shard's distance from this point contributes to how strongly it moves.", "Moving that strike higher or lower."),
    "cell_size_mm": ("Cell size", "Sets the physical spacing of the shared halftone matrix in millimeters. Smaller values preserve finer tonal detail but create more marks, larger files, and longer processing times.", "Choosing a coarse or fine screen for a printed newspaper image."),
    "minimum_dot_ratio": ("Minimum dot ratio", "Sets the smallest mark diameter or width as a fraction of one matrix cell. The default 0.48 keeps bright-color marks near half-cell width so they remain practical to engrave.", "Choosing how small the faintest printable ink dot may become."),
    "non_black_dot_density": ("Non-Black dot density", "Multiplies the engraved area of every non-Black halftone mark without changing the matrix spacing. The default 2.30 increases color-mark area while Black remains at its tone-calculated size. Marks are capped at the cell boundary so neighboring dots cannot overlap.", "Increasing ink coverage for process colors while leaving the Black plate unchanged."),
    "maximum_dot_ratio": ("Maximum dot ratio", "Sets the largest mark diameter or width as a fraction of one matrix cell. Values below 1 retain space between even the darkest marks.", "Limiting how much of each screen cell the darkest ink dot can occupy."),
    "minimum_glyph_ratio": ("Minimum glyph ratio", "Sets the smallest symbol width as a fraction of one matrix cell. Larger values make the lightest sampled areas more visible and reduce unengraved space.", "Choosing the smallest type size that a patterned printing screen is allowed to use."),
    "maximum_glyph_ratio": ("Maximum glyph ratio", "Sets the largest symbol width as a fraction of one matrix cell. Values below 1 preserve separation between symbols in the darkest sampled areas.", "Limiting how large each mosaic symbol can become inside its tile."),
    "glyph_size_source": ("Glyph size source", "Source Brightness sizes each glyph from the original artwork's grayscale brightness at that cell. Seeded Variation distributes deterministic sizes across the selected minimum and maximum range, including within areas that use the same color swatch.", "Choosing whether mosaic tile sizes follow the picture's shading or a repeatable varied pattern."),
    "non_black_glyph_density": ("Non-Black glyph density", "Increases the size-derived engraved area of non-Black symbols while leaving Black at its calculated size. Glyph Geometry preserves the selected minimum and maximum glyph sizes instead of flattening larger values against the cell boundary.", "Increasing the coverage of colored printing marks without making the Black plate heavier."),
    "glyph_rotation": ("Glyph rotation", "Rotates each selected symbol inside the already rotated matrix without moving its center or changing cell ownership.", "Turning every stamp on a sheet while leaving the sheet itself in place."),
    "random_rotation": ("Random rotation", "Gives every generated Glyph or Krasnow cell its own deterministic orientation. The same Seed recreates the same layout; changing Seed produces a different arrangement. Krasnow placements that would overlap are omitted so cells are not double engraved.", "Scattering individual stamps so each one points in a different direction while keeping the result reproducible."),
    "tone_curve": ("Tone curve", "Shapes how quickly marks grow between light and dark source values without changing the selected minimum and maximum sizes.", "Adjusting a photographic curve to emphasize highlights or shadows."),
    "contrast": ("Contrast", "Expands or compresses the tonal difference between light and dark marks around the midpoint.", "Increasing print contrast so pale dots shrink while dark dots grow."),
    "grid_angle": ("Grid angle", "Rotates the entire shared dot matrix while preserving exclusive ownership of each cell by one swatch.", "Turning a sheet of halftone screen before exposing an image through it."),
    "square_dots": ("Square dots", "Changes the marks from circles to grid-aligned squares.", "Switching a printing screen from round ink dots to square pixels."),
    "invert": ("Invert", "Reverses the tonal relationship so lighter source areas receive larger marks and darker areas receive smaller marks.", "Making a photographic negative of the screen pattern."),
    "black_only": ("Black only", "Places every generated mark on the official Black swatch layer while retaining source-luminance-driven dot sizes. A Material Library or saved palette must have an assigned Black Cut Setting Entry.", "Printing a conventional newspaper halftone with only black ink."),
    "dot_pitch_mm": ("Dot pitch", "Sets the physical center-to-center spacing of the optical mixing marks. Smaller spacing improves viewing-distance blending but increases mark count, file size, and sensitivity to laser spot size.", "Choosing how fine the colored dots are on a printed image."),
    "mix_cell_dots": ("Mixing cell dots", "Sets the width and height, in dots, of each ratio cell. Larger values provide finer two-color ratio steps but represent source-color changes over a larger physical area.", "Using more tiles in each mosaic block so its color ratio can be measured more precisely."),
    "dot_size_ratio": ("Dot size ratio", "Sets each mark's diameter or width as a fraction of Dot Pitch. Lower values leave more unmarked metal between dots; higher values increase coverage without allowing neighboring marks to overlap.", "Changing the diameter of printed dots without moving their centers."),
    "direct_color_preference": ("Direct color preference", "Penalizes two-swatch mixtures so a nearby direct swatch is retained unless mixing improves the predicted match enough. Higher values create fewer mixtures and generally simpler projects.", "Choosing a paint straight from the tube unless mixing clearly improves the match."),
    "keep_available_colors_as_vectors": ("Keep available colors as vectors", "Keeps ordinary continuous vector geometry wherever a palette swatch adequately represents the source color. Turn it off to render direct matches and calculated mixtures alike with the dot matrix.", "Printing colors already available as solid ink while screening only colors that need to be mixed."),
    "hue_shift": ("Hue shift", "Rotates the predicted physical swatch colors before mixture selection to compensate approximately for a consistent warm, cool, or hue-direction error.", "Turning the reference color wheel to compensate for a consistent tint."),
    "saturation_gain": ("Saturation gain", "Scales the predicted saturation of every available swatch before calculating mixtures. Use values below 1 when engraved colors appear duller than their declared swatches and values above 1 when they appear stronger.", "Adjusting a global color-intensity control before mixing paint."),
    "brightness_gamma": ("Brightness gamma", "Curves the predicted brightness of available swatches before mixture selection. Values above 1 predict darker physical results; values below 1 predict brighter results.", "Correcting a display that consistently renders midtones too dark or too light."),
    "dot_influence": ("Dot influence", "Changes how strongly the minority swatch is predicted to affect a mixture compared with its geometric dot count. Values above 1 make minority dots count more; values below 1 make them count less.", "Accounting for a strong pigment that changes a mixture even when only a little is present."),
    "neutral_bias": ("Neutral bias", "Discourages or favors Black, gray, and low-saturation swatches during mixture selection. Positive values reduce their use; negative values invite them into more mixtures.", "Deciding how readily gray paint may be added to every color mixture."),
    "pattern_seed": ("Pattern seed", "Changes the repeatable distribution order of component-color dots without changing the selected ratios. The same value recreates the same layout.", "Rearranging the same quantities of colored tiles while preserving their totals."),
    "speed_spread": ("Speed spread", "Contracts or expands each fauxlographic layer's calculated speed difference around the unchanged 1-micron anchor speed.", "Moving evenly spaced marks closer to or farther from a fixed center mark."),
    "gradient_top": ("Gradient top", "Sets the grayscale correction value at the top edge of the artwork.", "Choosing the first shade on a vertical calibration strip."),
    "gradient_bottom": ("Gradient bottom", "Sets the grayscale correction value at the bottom edge of the artwork.", "Choosing the last shade on a vertical calibration strip."),
    "gradient_curve": ("Gradient curve", "Bends the correction transition toward the top or bottom while preserving its endpoints.", "Changing a straight dimmer fade into an ease-in or ease-out fade."),
    "hue_rotation": ("Hue rotation", "Rotates artwork hues around Ben's pitch-code sequence before correction.", "Turning a labeled color wheel until its red mark aligns with a reference notch."),
    "saturation_cutoff": ("Saturation cutoff", "Treats colors below this saturation as neutral and applies only the viewing correction.", "Ignoring faint color casts on a gray calibration card."),
    "patch_size_mm": ("Patch size", "Sets the physical width and height of each local open-line grating cell.", "Changing the size of tiles that each hold their own hatch pattern."),
    "line_spacing_mm": ("Line spacing", "Sets the physical spacing between neighboring generated paths or flow seeds. Smaller values create denser geometry and larger files.", "Moving the ruled lines on graph paper closer together or farther apart."),
    "abstraction": ("Overall recognizability", "Coordinates the Structure Tensor Flow treatment from 0 for Photorealistic to 1 for Abstract. The Photorealistic end uses denser, broader, shorter, locally responsive ribbons; the Abstract end uses fewer, thinner, longer ribbons guided by a more broadly averaged field.", "Moving between a detailed woven portrait and a sparse flowing line study."),
    "line_length_mm": ("Line length", "Sets the nominal physical length of each tensor-flow ribbon before local coherence adjusts it.", "Choosing between short brush marks and long strands of combed fiber."),
    "ribbon_width_mm": ("Ribbon width", "Sets the physical width of each buffered tensor-flow path.", "Changing from a fine pen nib to a broader marker."),
    "minimum_ribbon_width_mm": ("Minimum ribbon width", "Sets the narrowest physical width a tensor-flow ribbon may use after its local tone and directional coherence are evaluated.", "Choosing the finest nib available to a variable-width drawing pen."),
    "maximum_ribbon_width_mm": ("Maximum ribbon width", "Sets the widest physical width a tensor-flow ribbon may use. Values below the minimum are normalized so the smaller endpoint remains the minimum.", "Choosing the broadest nib available to a variable-width drawing pen."),
    "minimum_color_run_mm": ("Minimum color run", "Merges very short color fragments within the ribbon output into the touching color that shares the longest boundary. Zero disables this cleanup.", "Removing tiny thread-color changes from a woven pattern and continuing the neighboring thread instead."),
    "width_tone_influence": ("Width tone influence", "Controls how strongly source brightness changes ribbon width within the selected minimum and maximum range.", "Letting the light and dark areas of a photograph control how firmly a brush is pressed."),
    "width_coherence_influence": ("Width coherence influence", "Controls how strongly tensor directional confidence changes ribbon width within the selected minimum and maximum range.", "Using broader strokes where nearby fibers agree on their direction and finer strokes where the flow is uncertain."),
    "step_size_mm": ("Step size", "Sets the integration step used while tracing each curved flow line. Smaller steps follow tight changes more faithfully but add vector points and processing work.", "Taking smaller steps while walking a curved trail so each turn is followed more precisely."),
    "source_blur_px": ("Source blur", "Smooths source luminance before gradients are measured, reducing pixel noise and very fine directional changes.", "Softening a photograph before tracing its major edges."),
    "tensor_smoothing_px": ("Tensor smoothing", "Controls how broadly nearby gradients are averaged into the local direction field. Larger values create broader, calmer directional sweeps.", "Using a wider comb to align nearby strands into one shared direction."),
    "coherence_cutoff": ("Coherence cutoff", "Suppresses ribbons where the structure tensor has no sufficiently dominant direction. Zero retains structures in flat areas; higher values increasingly keep only confidently directed areas.", "Erasing compass arrows where nearby evidence does not agree on a direction."),
    "coherence_influence": ("Coherence influence", "Controls how strongly directional confidence shortens ribbons. Zero keeps the nominal line length everywhere; one makes uncertain regions much shorter than strongly directed regions.", "Letting confident currents carry a leaf farther while weak currents move it only a short distance."),
    "flow_rotation": ("Flow rotation", "Rotates every sampled tensor tangent by the selected number of degrees without changing the detected source structure.", "Turning every stroke relative to the contour it originally followed."),
    "seed_jitter": ("Seed jitter", "Offsets streamline starting points by a repeatable fraction of their spacing so the pattern becomes less grid-like.", "Nudging evenly planted rows into a more organic arrangement."),
    "hue_line_spacing_minimum_mm": ("Hue line spacing minimum", "Sets the visible line spacing assigned to the violet end of Krasnow's approximate wavelength ordering. Blue, green, yellow, orange, and red interpolate upward from this endpoint; neutral colors continue to use Line Spacing.", "Setting the tightest end of a color-ordered ruler for the generated hatch lines."),
    "hue_line_spacing_maximum_mm": ("Hue line spacing maximum", "Sets the visible line spacing assigned to the red end of Krasnow's approximate wavelength ordering. Equal minimum and maximum values keep every chromatic color at one uniform spacing.", "Setting the widest end of a color-ordered ruler for the generated hatch lines."),
    "angle_min": ("Angle minimum", "Sets the open-path angle selected by black source luminance.", "Assigning the dark end of a dimmer to the first position on a protractor."),
    "angle_max": ("Angle maximum", "Sets the open-path angle selected by white source luminance.", "Assigning the bright end of a dimmer to the last position on a protractor."),
}

filter_manifest = abstract_filter_manifest()
for slug, (name, behavior) in FILTER_PAGES.items():
    DOCS[f"{slug}-filter"] = _page(
        f"{name} Abstract Vector Filter",
        f"Use the {name} preset to transform raster-derived color regions into stylized vector geometry for SVG or LightBurn laser artwork.",
        f"{name} is an optional creative preset that {behavior}. It uses Rasterizer's normal swatch, job-processing, and export logic.",
        [("Best use", ["Start with artwork that has a recognizable subject, strong contrast, or clearly separated color regions so the abstract effect has useful structure to transform. The effect is intentionally interpretive, so test it with reduced processing dimensions before committing to a detailed export."]), ("Controls", ["The preset panel exposes only the parameters supported by this filter. Depending on the preset and source artwork, more aggressive or denser settings can increase processing time, memory use, and vector-object count."]), ("Output", ["The transformed geometry remains organized according to its matching Rasterizer swatches. In a Material Library-backed job, it is placed on the corresponding LightBurn layers configured with the matched cut settings. Inspect the generated .svg file and, when produced, the .lbrn2 LightBurn project before engraving."])],
        ["abstract-filters", "abstract-filter-reference", "reduce-lightburn-object-count"],
    )
    module_slug = slug.replace("-", "_")
    filter_data = filter_manifest.get(module_slug, {})
    defaults = filter_data.get("defaults", {})
    DOCS[f"{slug}-filter"]["controls"] = [
        {
            "name": control["name"], "label": CONTROL_GUIDES[control["name"]][0],
            "effect": CONTROL_GUIDES[control["name"]][1], "analogy": CONTROL_GUIDES[control["name"]][2],
            "default": defaults.get(control["name"]), "minimum": control["min"],
            "maximum": control["max"], "step": control["step"],
        }
        for control in filter_data.get("controls", [])
    ]

